export interface AnnaAnalysisInput {
  userName?: string;
  totalCalories: number;
  totalProtein: number;
  totalFat: number;
  totalCarbohydrates: number;
  totalFiber: number;
  calTarget?: number;
  topIngredients: string[];
  nonWfpbIngredients?: string[];
  hasNonWfpb?: boolean;
  totalMass?: number;
  effWater: number;
  waterTarget: number;
  expectedWaterByNow: number;
  deficitNow: number;
  remainingMinutes: number;
  paceNeeded: number;
  effSleep: number;
  sleepTarget?: number;
  effWeight?: number;
  effSystolic?: number;
  effDiastolic?: number;
  effPulse?: number;
  leaderName?: string;
  leaderPct?: number;
  secondLeaderName?: string;
  secondLeaderPct?: number;
  habitDoneCount?: number;
  cookedDishCount?: number;
  totalDishCount?: number;
  activityMinutes?: number;
  hasBreakfast?: boolean;
  hasLunch?: boolean;
  hasDinner?: boolean;
  activeTab?: string;
  digestionCount?: number;
  latestBristolType?: number;
  latestBristolLabel?: string;
  digestionScorePct?: number;
  activityTypesList?: string[];
  activityMinutesTotal?: number;
}

export function pickVariant(variants: string[], seed: number = 0): string {
  if (!variants || variants.length === 0) return "";
  const index = Math.abs(seed) % variants.length;
  return variants[index];
}

function formatTopIngredients(ings?: string[]): string {
  if (!ings || ings.length === 0) return "цельных растительных компонентов";
  return ings.slice(0, 4).map(s => s.trim()).filter(Boolean).join(", ");
}

function formatNonWfpbList(ings?: string[]): string {
  if (!ings || ings.length === 0) return "компоненты вне протокола WFPB";
  return ings.slice(0, 3).map(s => s.trim()).filter(Boolean).join(", ");
}

function formatBiometricsString(input: AnnaAnalysisInput): { bpBioText: string; bpInBracketText: string } {
  const hasBP = Boolean(input.effSystolic && input.effDiastolic);
  const pulseStr = input.effPulse ? `, ЧСС ${input.effPulse} уд/мин` : "";

  if (hasBP) {
    const bpBase = `АД ${input.effSystolic}/${input.effDiastolic} мм рт. ст.${pulseStr}`;
    return {
      bpBioText: bpBase,
      bpInBracketText: `, ${bpBase}`
    };
  }

  return {
    bpBioText: "в норме",
    bpInBracketText: ""
  };
}

