export type NonWfpbCategory = "red_meat" | "poultry" | "fish" | "dairy_eggs" | "processed" | "general";

export function detectNonWfpbCategory(ings?: string[]): NonWfpbCategory {
  if (!ings || ings.length === 0) return "general";
  const text = ings.join(" ").toLowerCase();

  if (/колбас|сосиск|ветчин|паштет|майонез/.test(text)) return "processed";
  if (/баранин|говядин|свинин|телятин|фарш|мяс|сало|бекон/.test(text)) return "red_meat";
  if (/куриц|курк|индейк|утк|гус|птиц/.test(text)) return "poultry";
  if (/рыб|лосос|форел|семг|тунец|треск|минтай|скумбри|сельдь|селедк|креветк|кальмар|миди|осьминог|краб|морепродукт/.test(text)) return "fish";
  if (/творог|сыр|молок|сливк|масло сливочн|сметан|кефир|йогурт|ряженк|яйц|яичн|омлет/.test(text)) return "dairy_eggs";

  return "general";
}

